window.POETRY_REGISTER("v5-strict-13-14-0-937f4cef1ad0.js",{"poems":[[57946,2],[143405,7],[272035,7],[288143,7],[345477,9]],"pairs":[["如第二首以秋灰夏火为对即是","在卢照邻刘允济诗中始见此二语",0],["安知东之主生兮西配刑而主杀","斗建寅而气分兮畴为四时之消息",1],["东升气而敷生兮西或成而害戕","强名之曰自然兮曷足以究其必至",1],["姑置之而勿校兮任万物之自成","游小智于太初兮何异夏虫之语冰",1],["旷任之而勿疑兮万里会而一平","夫何造物者开予兮神飘飘而不居",1],["我将赴而远游兮招神圣以为徒","腾九螭之奔轮兮追飞电而揽奔风",1],["盖自智而慧者笔下有天真之悟","而惟清与净者胸中无一点之尘也",2],["袭正轨之茂则兮耻践迹而循科","御长辕而猎太空兮摧九折之峨峨",3],["溯孤鸿之影灭兮书不得而远寄","惊兔走之伏莽兮那思驰骋而发狂",4]]});
